import { _decorator, Color, Component, Graphics, Label } from 'cc';
import type { Bus } from '../../Engine/Bus';
import { HallEvents } from '../HallEvents';
import { gridToWorld, GRID_SIZE } from '../Config/GridConfig';
import type { GhostState } from '../System/GhostSystem';
import { BUILDING_CONFIG } from '../Config/BuildingConfig';

const { ccclass } = _decorator;

@ccclass('GhostView')
export class GhostView extends Component {

    private _bus: Bus = null!;
    private _g: Graphics = null!;
    private _label: Label = null!;

    setup(bus: Bus): void {
        this._bus = bus;
        this._bus.on(HallEvents.GHOST_STATE_CHANGED, this._onState, this);
    }

    onLoad() {
        this._g = this.node.addComponent(Graphics);
        this._label = this.node.addComponent(Label);
        this._label.fontSize = 18;
        this.node.active = false;
    }

    onDestroy(): void {
        this._bus?.off(HallEvents.GHOST_STATE_CHANGED, this._onState, this);
    }

    private _onState(s: GhostState): void {
        this.node.active = s.active;
        if (!s.active) return;

        const w = gridToWorld(s.gridX, s.gridY);
        this.node.setPosition(w.x, w.y);

        this._draw(s.valid);

        const cfg = BUILDING_CONFIG[s.typeId];
        this._label.string = cfg ? `${cfg.name}\n${cfg.cost}G` : '';
        this._label.color = s.valid
            ? new Color(255, 255, 255, 255)
            : new Color(255, 120, 120, 255);
    }

    private _draw(valid: boolean): void {
        this._g.clear();
        this._g.fillColor = valid
            ? new Color(80, 200, 120, 160)     // 半透明绿
            : new Color(220, 80, 80, 160);     // 半透明红
        const half = GRID_SIZE / 2 - 6;
        this._g.rect(-half, -half, half * 2, half * 2);
        this._g.fill();
    }
}